<script setup lang="ts">
import { ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { usePetStore } from '@/stores/pet'
type Tab = 'photos' | 'diaries' | 'timeline'
const current = ref<Tab>('photos'); const store = usePetStore()
const tabs: Array<{ value: Tab; label: string }> = [{ value: 'photos', label: '照片' }, { value: 'diaries', label: '日记' }, { value: 'timeline', label: '时间轴' }]
onLoad((options) => { if (options?.tab && ['photos', 'diaries', 'timeline'].includes(options.tab)) current.value = options.tab as Tab })
function add() { uni.showToast({ title: current.value === 'photos' ? '已打开照片上传' : current.value === 'diaries' ? '已打开日记编辑器' : '已打开事件记录', icon: 'none' }) }
function photoSearch() { uni.navigateTo({ url: '/pages/ai/index?context=photos' }) }
</script>
<template><view class="screen"><view class="tabs"><view v-for="tab in tabs" :key="tab.value" :class="{ active: current === tab.value }" @tap="current = tab.value">{{ tab.label }}</view></view><view class="body"><template v-if="current === 'photos'"><view class="search" @tap="photoSearch"><uni-icons type="search" size="18" color="#8E8E93" /><text>用一句话找到豆包的照片</text><uni-icons type="arrow-right" size="15" color="#C7C7CC" /></view><text class="month">2026 年 8 月 · 12 张</text><view class="grid"><image v-for="i in 6" :key="i" :src="store.pet.avatar" mode="aspectFill" /><image v-for="i in 3" :key="`earlier-${i}`" :src="store.pet.avatar" mode="aspectFill" class="muted" /></view></template><template v-else-if="current === 'diaries'"><view class="diary-new" @tap="add"><view><uni-icons type="compose-filled" size="19" color="#007AFF" /></view><text>写一篇日记</text><uni-icons type="arrow-right" size="15" color="#C7C7CC" /></view><view class="diary"><image :src="store.pet.avatar" mode="aspectFill" /><view><text>阳台的午后</text><text>阳光、纸箱，还有一只困得不行的小猫。</text><text>2026 年 8 月 15 日</text></view></view><view class="diary"><image :src="store.pet.avatar" mode="aspectFill" /><view><text>去年的今天</text><text>你和豆包在阳台晒了一整个下午的太阳。</text><text>2025 年 8 月 18 日</text></view></view></template><template v-else><view class="timeline-intro"><text>豆包的生活书</text><text>每条记录都会在这里，变成一段独特回忆。</text></view><view class="timeline"><view v-for="log in store.logs" :key="log.id" class="timeline-row"><view class="timeline-mark"><view :class="log.tint"><uni-icons :type="log.icon" size="15" :color="log.tint === 'green' ? '#34C759' : log.tint === 'orange' ? '#FF9500' : '#007AFF'" /></view></view><view><text>{{ log.date }} · {{ log.time }}</text><text>{{ log.title }}</text><text>{{ log.value }}</text></view></view></view></template><view class="spacer" /></view><view class="add" @tap="add"><uni-icons type="plus" size="23" color="#FFFFFF" /></view></view></template>
<style scoped lang="scss">
@use '@/styles/tokens.scss' as *;
.screen { min-height: 100vh; background: $canvas; }.tabs { display: flex; height: 90rpx; gap: 44rpx; padding: 0 32rpx; background: $surface; }.tabs view { position: relative; display: flex; align-items: center; color: $tertiary; font-size: 28rpx; }.tabs .active { color: $ink; font-weight: 600; }.tabs .active::after { position: absolute; right: 5rpx; bottom: 0; left: 5rpx; height: 5rpx; border-radius: 99rpx; background: $blue; content: ''; }.body { padding: 28rpx 32rpx; }.search, .diary-new { display: flex; align-items: center; gap: 14rpx; padding: 20rpx; border-radius: 23rpx; background: $surface; }.search text { flex: 1; color: $tertiary; font-size: 24rpx; }.month { display: block; margin: 36rpx 0 15rpx 24rpx; color: $secondary; font-size: 24rpx; font-weight: 500; }.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10rpx; }.grid image { width: 100%; height: 214rpx; border-radius: 17rpx; }.grid .muted { opacity: .76; }.diary-new > view { display: flex; width: 54rpx; height: 54rpx; align-items: center; justify-content: center; border-radius: 17rpx; background: $blue-soft; }.diary-new > text { flex: 1; font-size: 27rpx; font-weight: 600; }.diary { display: flex; gap: 17rpx; margin-top: 16rpx; padding: 17rpx; border-radius: 25rpx; background: $surface; }.diary image { width: 148rpx; height: 148rpx; border-radius: 17rpx; }.diary > view { display: flex; flex: 1; flex-direction: column; gap: 7rpx; }.diary text:first-child { color: $ink; font-size: 27rpx; font-weight: 600; }.diary text:nth-child(2) { color: $secondary; font-size: 21rpx; line-height: 1.45; }.diary text:last-child { margin-top: auto; color: $tertiary; font-size: 18rpx; }.timeline-intro { display: flex; flex-direction: column; gap: 9rpx; padding: 24rpx; border-radius: 28rpx; background: $surface; }.timeline-intro text:first-child { font-size: 32rpx; font-weight: 700; }.timeline-intro text:last-child { color: $tertiary; font-size: 22rpx; }.timeline { margin-top: 34rpx; }.timeline-row { display: flex; min-height: 120rpx; }.timeline-mark { position: relative; width: 70rpx; flex: 0 0 70rpx; }.timeline-mark::after { position: absolute; top: 52rpx; bottom: -1rpx; left: 27rpx; width: 2rpx; background: $separator-strong; content: ''; }.timeline-row:last-child .timeline-mark::after { display: none; }.timeline-mark > view { position: relative; z-index: 1; display: flex; width: 54rpx; height: 54rpx; align-items: center; justify-content: center; border-radius: 50%; background: $surface; }.timeline-mark .blue { background: $blue-soft; }.timeline-mark .green { background: #EAF8EF; }.timeline-mark .orange { background: #FFF3E2; }.timeline-row > view:last-child { display: flex; flex: 1; flex-direction: column; gap: 6rpx; padding: 3rpx 0 25rpx; }.timeline-row text:first-child { color: $tertiary; font-size: 19rpx; }.timeline-row text:nth-child(2) { color: $ink; font-size: 27rpx; font-weight: 600; }.timeline-row text:last-child { color: $secondary; font-size: 22rpx; }.spacer { height: 90rpx; }.add { position: fixed; right: 32rpx; bottom: 40rpx; display: flex; width: 92rpx; height: 92rpx; align-items: center; justify-content: center; border: 5rpx solid #fff; border-radius: 50%; background: $blue; box-shadow: 0 10rpx 22rpx rgba(0,122,255,.25); }
</style>
